import{_ as a,c as e,o as d,ag as l}from"./chunks/framework.Bkod66qp.js";const _=JSON.parse('{"title":"- 1단계 제목: CustomHeading1","description":"","frontmatter":{},"headers":[],"relativePath":"manual/매뉴얼 작성지침 서식파일.md","filePath":"manual/매뉴얼 작성지침 서식파일.md"}'),o={name:"manual/매뉴얼 작성지침 서식파일.md"};function r(i,t,h,s,n,u){return d(),e("div",null,t[0]||(t[0]=[l('<p>📘 문서 작성 지침 (Word 작성안내)</p><ol><li>이 템플릿은 Markdown 변환을 염두에 두고 설계되었습니다. 반드시 아래 스타일만을 사용해 주세요. 한글로 작성할 때는 다소 빈약해 보일 수 있지만, 제공되는 홈페이지에서의 검색 편의성과 양식 통일을 통한 가독성 향상을 위해 반드시 지켜야 합니다. 이 가이드라인을 어길 경우, 추후 MD 변환 시 오류가 발생할 가능성이 높습니다.</li><li>이 서식을 활용하여 수정해보세요</li><li>스타일 적용 방법:</li></ol><ul><li>단락을 선택한 후 [홈] 탭 &gt; [스타일] 그룹에서 &#39;Custom...&#39;으로 시작하는 스타일을 선택하세요.</li><li>단축키: Shift+Ctrl+Alt + Ctrl + s → Custom…으로 시작하는 형식만 선택</li></ul><ol start="4"><li>제목 작성:</li></ol><h1 id="_1단계-제목-customheading1" tabindex="-1">- 1단계 제목: CustomHeading1 <a class="header-anchor" href="#_1단계-제목-customheading1" aria-label="Permalink to &quot;- 1단계 제목: CustomHeading1&quot;">​</a></h1><h2 id="_2단계-제목-customheading2" tabindex="-1">- 2단계 제목: CustomHeading2 <a class="header-anchor" href="#_2단계-제목-customheading2" aria-label="Permalink to &quot;- 2단계 제목: CustomHeading2&quot;">​</a></h2><h3 id="_3단계-제목-customheading3" tabindex="-1">- 3단계 제목: CustomHeading3 <a class="header-anchor" href="#_3단계-제목-customheading3" aria-label="Permalink to &quot;- 3단계 제목: CustomHeading3&quot;">​</a></h3><ol start="5"><li>본문 작성: CustomBodyText 스타일을 사용하세요.</li></ol><blockquote><ol start="6"><li>인용문 작성: CustomQuote 스타일을 사용하세요.</li></ol></blockquote><div class="strong-paragraph">7. 강조 단락: CustomStrongParagraph 스타일을 사용하세요.</div> ``` 8. 코드 블록: ``` ``` - CustomCodeBlock 스타일을 사용하세요. ``` ``` - 글꼴은 Consolas, 크기 10pt입니다. ``` 9. 표 삽입: - [삽입] &gt; [표]를 클릭하여 표를 추가하세요. - 첫 행은 머리글로 사용하고, 병합이 필요한 경우 셀 병합 기능을 사용하세요. <ol start="10"><li>이미지 삽입:</li></ol><ul><li>[삽입] &gt; [그림]을 클릭하여 이미지 추가</li><li>이미지 아래에 캡션을 추가하려면 [참조] &gt; [캡션 삽입]</li></ul><figcaption>- 캡션은 CustomCaption 스타일을 사용하세요.</figcaption> 11. YAML 메타데이터는 문서 맨 앞에 코드 블록으로 삽입됩니다. =&gt; 향후 챗봇, 생성형 Ai 활용 시 매우 유용한 정보이므로 매뉴얼 제작시 같이 첨부해주세요. 12. 문서 저장 후에는 경영기획팀에 제출해주세요. <p>예시 매뉴얼</p><p>--- #YAML 정보 title: 복무근태매뉴얼 doc_id: SFAC-HR-2025-001 version: 1.0 department: 인사팀 author: 김인사 approver: 김팀장 created_at: 2025-01-01 updated_at: 2025-06-30 effective_date: 2025-07-01 tags: [기본복무, 유연근무, 휴가제도] related_docs: - SFAC-FIN-2023-045 - SFAC-HR-2024-012 status: 시행중 summary: 25년부로 규정개정내역 반영함 source_xml: <a href="https://intra.sfac.or.kr/docs/SFAC-FIN-2024-001.xml" target="_blank" rel="noreferrer">https://intra.sfac.or.kr/docs/SFAC-FIN-2024-001.xml</a> ---</p><h1 id="_1-기본복무" tabindex="-1">1. 기본복무 <a class="header-anchor" href="#_1-기본복무" aria-label="Permalink to &quot;1. 기본복무&quot;">​</a></h1><h2 id="가-일일근로시간" tabindex="-1">가. 일일근로시간 <a class="header-anchor" href="#가-일일근로시간" aria-label="Permalink to &quot;가. 일일근로시간&quot;">​</a></h2><ul><li>휴게시간을 제하고 8시간 원칙(기준근태 09:00~18:00) - 유연근무 사용 시 가급적 7:00-22:00 내에서 근무시간 조정 (공동근무시간 11:00-12:00, 13:00-16:00)</li></ul><h2 id="나-휴게시간" tabindex="-1">나. 휴게시간 <a class="header-anchor" href="#나-휴게시간" aria-label="Permalink to &quot;나. 휴게시간&quot;">​</a></h2><ul><li>1시간(12:00~13:00)</li></ul><h2 id="다-공통사항" tabindex="-1">다. 공통사항 <a class="header-anchor" href="#다-공통사항" aria-label="Permalink to &quot;다. 공통사항&quot;">​</a></h2><ul><li>유연근무, 휴가 등은 사전신청이 원칙이나, 불가피한 사유(ERP 시스템 오류, 교통사고 )가 발생한 경우 그 사유를 명확히 하여 소속 부서장에게 유선 또는 서면보고를 해야하며, 사후 신청 시 기안문에 사유서(별첨 1)를 첨부하여 부서장이 확인 및 결재 ※ 복무규정 제16조(출근 및 결근)에 따름.</li></ul><h2 id="다-사전-상신-인정-기준-예시" tabindex="-1">다. 사전 상신 인정 기준(예시) <a class="header-anchor" href="#다-사전-상신-인정-기준-예시" aria-label="Permalink to &quot;다. 사전  상신 인정 기준(예시)&quot;">​</a></h2><ul><li>10:00-19:00 탄력근무 신청 시 : 9:00 이전에 상신해야 사전 신청으로 인정 → 본래 기준근태가 9:00 이므로, 9:00 이후 상신할 경우 이미 지각에 해당</li><li>8:00-17:00 탄력근무 신청 시 : 8:00 이후 상신하면 사후 신청에 해당</li></ul><h1 id="_2-유연근무제를-통한-근로시간-변경" tabindex="-1">2. 유연근무제를 통한 근로시간 변경 <a class="header-anchor" href="#_2-유연근무제를-통한-근로시간-변경" aria-label="Permalink to &quot;2. 유연근무제를 통한 근로시간 변경&quot;">​</a></h1><table><thead><tr><th> 서울문화재단 복무‧근태 매뉴얼 </th></tr></thead><tbody></tbody></table><table><thead><tr><th> 항목 </th><th> 대상 </th><th> 내용 </th><th> 운영방법 </th></tr></thead><tbody><tr><td> 탄력근무제 </td><td> 전부서 모든직원 </td><td> 법정근무시간인 1일 8시간의 근무체제를 유지하면서, 본인의 출퇴근시간을 1일 단위로 자율적으로 결정할 수 있는 제도 </td><td> - 1일 단위 원칙 - 시행 시점 전까지 사전 상신 (인사시스템-개인근태관리(NEW)) ※ 협조 없음 </td></tr><tr><td> 시차출퇴근제 </td><td> 전부서 모든직원 </td><td> 소정근무시간인 1일 8시간의 근무체제를 유지하면서, 본인의 출퇴근 시간을 1주 단위로 자율적으로 결정할 수 있는 제도 (육아, 교통체증 등 개인사유로 신청 가능) </td><td> - 최소 1주일 단위 원칙 - 시행 시점 전까지 사전 상신 (인사시스템-유연근무신청) ※ 협조 : 복무담당자 </td></tr><tr><td> 탄력적 근로시간제 </td><td> 전부서 모든직원 </td><td> 특정 근로일 또는 주(週)의 근로시간을 연장 시키는 대신 다른 근로일 또는 다른 주의 근로시간을 단축시킴으로써 일정기간의 평균 근로시간을 법정근로시간(주 40시간) 내로 맞추는 제도 2주 이내 : 주당 최대 48시간 근무 가능 3월 이내 : 주당 최대 52시간 근무 가능 </td><td> - 최소 2주 단위 원칙 - 시행 시점 전까지 사전 상신 (인사시스템-유연근무신청) ※ 협조 : 복무담당자 </td></tr></tbody></table><table><thead><tr><th> 항목 </th><th> 대상 </th><th> 내용 </th><th> 운영방법 </th></tr></thead><tbody><tr><td> 근무시간 선택제 </td><td> 적용 대상에 해당하는 직원 </td><td> 법정 근무시간인 1일 8시간의 근무체제에서 구애받지 않고 1일 4-12시간 범위 내, 주 3.5일~5일 까지 본인의 출퇴근 시간을 자율 조정하여 주 40시간을 준수하는 근무제도 - 적용대상 : 임신, 육아, 간병, 신병, 학업 등 의 사유로 신청한 경우, 부서에서 근무 시간선택제에 적합하다고 판단되는 업무 </td><td> - 시행예정일 3일 전까지, 1개월 단위 신청 - 계획 내부결재 후 인사시스템 등록 (인사시스템-유연근무신청) - 근무요일 및 시간은 자율 선택. 단, 공동근무시간대 설정하여 근무하는 것을 원칙으로 함 - 1일의 총 근무 가능 시간대는 07:00~22:00으로 함 ※ 1일 최대 근무시간 12시간 (점심, 저녁 휴게시간 제외) ※ 주 40시간 준수에 위배되지 않도록 다른 근무일의 근무시간 조정 ※ 연차를 사용할 경우, 해당 일의 근무 시간만큼 공제 ※ 협조 : 복무담당자, 인사팀장 </td></tr><tr><td> 시간 선택제 근무 </td><td> 적용 대상에 해당하는 직원 </td><td> 주 40시간, 1일 8시간의 통상적인 근무시간보다 짧게 근무하며, 1일 최소 3시간 이상, 주 15~30 시간을 근무하는 제도 적용대상 : 임신, 육아, 간병, 신병, 학업 등의 사유로 신청한 경우 보수·성과급·연차·승진 등은 재직기간·근무 시간과 비례하여 산정하며, 고용노동부 운영 지침을 따름 </td><td> -전월 신청, 1개월 단위 신청 계획 내부결재 후 인사시스템 등록 (인사시스템-유연근무신청) - 주간근무 범위(09:00~18:00) 내에서 1일 최소 3시간 이상, 주 15~30시간 자율선택 - 연차계산 : 재직기간별 연가일수×시간제 근무 주근무시간/직원 주근무시간×8시간 - 일반 근무자와 동일하게 ‘일’단위 병가 및 특별휴가 허가 ※ 내부결재 협조 : 복무담당자, 인사팀장 </td></tr></tbody></table><table><thead><tr><th> 항목 </th><th> 내용 </th></tr></thead><tbody><tr><td> 예시 </td><td> 테스트 데이터 </td></tr></tbody></table>',31)]))}const m=a(o,[["render",r]]);export{_ as __pageData,m as default};
